"""Benchmark report (Markdown) generated from metrics.json; no number in it is typed by hand."""

from __future__ import annotations

from pathlib import Path


def _pass(v) -> str:
    return "n/a" if v is None else ("PASS" if v else "FAIL")


def write_report(m: dict, path: Path) -> Path:
    L = ["# Benchmark report", "",
         "Generated by `groundplan bench`. Every number below is recomputed from the raw captures and the laser/tape "
         "ground truth listed in `benchmark/manifest.yaml`.", "", "## Gates", "",
         "| gate | tier | threshold | result | status | detail |", "|---|---|---|---|---|---|"]
    for g in m["gates"]:
        L.append(f"| {g['name']} | {g['tier']} | {g['threshold']} | {g['value']} | {_pass(g['passed'])} | {g['detail']} |")

    L += ["", "## Repeatability (same room, same tier, two captures)", ""]
    if m["repeatability"]:
        for r in m["repeatability"]:
            L += [f"**{r['pair'][0]} vs {r['pair'][1]}** ({r['tier']}): {_pass(r['passed'])}", "",
                  "| room | wall | capture A (m) | capture B (m) | diff (mm) | tolerance (mm) | ok |", "|---|---|---|---|---|---|---|"]
            for row in r["rows"]:
                L.append(f"| {row['room']} | {row['wall']} | {row['a']:.3f} | {row['b']:.3f} | {row['diff'] * 1000:+.1f} | "
                         f"{row['tol'] * 1000:.1f} | {'yes' if row['ok'] else 'no'} |")
            L.append("")
    else:
        L.append("_no repeated captures in the manifest_")

    L += ["", "## Drift ablation (multi-room capture, correction on vs off)", ""]
    if m["drift_ablation"]:
        L += ["| capture | drift | footprint (m²) | footprint error | walls within max(2 cm,1%) | median wall error | adjacency |",
              "|---|---|---|---|---|---|---|"]
        for row in m["drift_ablation"]:
            for lab in ("on", "off"):
                d = row[lab]
                fe = "n/a" if d["footprint_err_pct"] is None else f"{d['footprint_err_pct']:+.2f}%"
                me = "n/a" if d["median_wall_err_cm"] is None else f"{d['median_wall_err_cm']:.2f} cm"
                L.append(f"| {row['capture']} | {lab} | {d['footprint_m2']:.2f} | {fe} | {d['walls_within']}/{d['walls']} | "
                         f"{me} | {d['adjacency']} |")
            L.append(f"\n_correction: {row['on']['drift_notes']}_\n")
    else:
        L.append("_no drift ablation in the manifest_")

    L += ["", "## Calibration (nominal 90% intervals)", "",
          "| tier | quantity | n | coverage | median interval width | median abs error | in 85-95% band |",
          "|---|---|---|---|---|---|---|"]
    for c in m["calibration"]:
        L.append(f"| {c['tier']} | {c['quantity']} | {c['n']} | {c['coverage']:.0%} | {c['median_interval_width']:.3f} | "
                 f"{c['median_abs_err']:.3f} | {'yes' if c['in_band'] else 'no'} |")

    if "head_to_head" in m:
        h = m["head_to_head"]
        rate = "n/a" if h["rate"] is None else f"{h['rate']:.0%}"
        L += ["", f"## Head-to-head vs {h['app']} {h['app_version']}", "",
              f"Beat or tie on **{h['beat_or_tie']}/{h['shared']}** shared dimensions "
              f"({rate}; gate >= 70%: {_pass(h['passed'])}). {h['tie_rule']}.", "",
              "| room | dimension | truth | ours | our error | app | app error | result |", "|---|---|---|---|---|---|---|---|"]
        for r in h["rows"]:
            oe = "n/a" if r["ours_err"] is None else f"{r['ours_err'] * 100:+.1f} cm"
            ov = "n/a" if r["ours"] is None else f"{r['ours']:.3f}"
            L.append(f"| {r['room']} | {r['dimension']} | {r['truth']:.3f} | {ov} | {oe} | {r['app']:.3f} | "
                     f"{r['app_err'] * 100:+.1f} cm | {r['result']} |")

    L += ["", "## Timing", "", "| capture | runtime (s) |", "|---|---|"]
    for k, v in m["timing_s"].items():
        L.append(f"| {k} | {v:.1f} |")

    L += ["", "## Per-capture detail", ""]
    for c in m["captures"]:
        L += [f"### {c['capture']} ({c['tier']})", "",
              f"rooms matched {c['rooms_matched']}/{c['rooms_gt']} (predicted {c['rooms_pred']}); adjacency "
              f"{c['adjacency_found']}/{c['adjacency_gt']} (+{c['adjacency_extra']} extra); overlaps {c['overlaps']}; "
              f"openings within 2 cm {c['openings_matched_within']}, missed {c['openings_missed']}, phantom "
              f"{c['openings_phantom']}{'; manual room mapping used' if c['manual_match'] else ''}", "",
              "| quantity | room | ref | truth | ours [90% interval] | error | covered |", "|---|---|---|---|---|---|---|"]
        for i in c["items"]:
            L.append(f"| {i['kind']} | {i['room']} | {i['ref']} | {i['truth']:.3f} | {i['value']:.3f} [{i['lo']:.3f}, "
                     f"{i['hi']:.3f}] | {i['err'] * 100:+.1f} cm ({i['rel'] * 100:+.1f}%) | {'yes' if i['covered'] else 'no'} |")
        L.append("")
    path.write_text("\n".join(L) + "\n", encoding="utf-8", newline="\n")
    return path
